dleplugin.mysqlinstall:
REPLACE INTO {prefix}_admin_sections (name, title, descr, icon, allow_groups) VALUES ('ai_content', 'AI Content', 'OpenAI ile İçerik Üretici', 'ai_icon.png', '1');
CREATE TABLE IF NOT EXISTS `{prefix}_ai_config` ( `id` int(11) NOT NULL AUTO_INCREMENT PRIMARY KEY, `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL, `value` text COLLATE utf8mb4_unicode_ci NOT NULL, `is_encrypted` tinyint(1) NOT NULL DEFAULT '0' ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{prefix}_ai_logs` ( `id` int(11) NOT NULL AUTO_INCREMENT PRIMARY KEY, `user_id` int(11) NOT NULL, `action` varchar(50) NOT NULL, `prompt` text, `response` text, `error` text, `ip` varchar(45), `date` datetime DEFAULT CURRENT_TIMESTAMP, KEY `user_id` (`user_id`), KEY `date` (`date`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `{prefix}_ai_config` (`name`, `value`, `is_encrypted`) VALUES ('api_key', '', 1), ('model', 'gpt-3.5-turbo', 0), ('max_tokens', '1000', 0), ('temperature', '0.7', 0), ('encryption_key', MD5(CONCAT(RAND(), NOW())), 1);

dleplugin.mysqldelete:
DELETE FROM {prefix}_admin_sections WHERE name = 'ai_content';
    DROP TABLE IF EXISTS `{prefix}_ai_config`;
    DROP TABLE IF EXISTS `{prefix}_ai_logs`;
